using System.Security.Cryptography;using System.Text;using CouponBook.Data;using CouponBook.Data.Entities;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;
namespace CouponBook.Business.Auth;
public record UserProfile(int Id,string FullName,string Mobile,string? Email,string Language,bool IsCustomer,bool IsProvider,bool IsAdmin);
public record OtpRequested(string Status,string? DevelopmentCode);
public class LoginResult{public string AccessToken{get;set;}="";public string TokenType{get;set;}="Bearer";public int ExpiresIn{get;set;}public UserProfile User{get;set;}=null!;}
public interface IAccountService{Task<ServiceResult<OtpRequested>> RequestOtpAsync(string mobile);Task<ServiceResult<LoginResult>> VerifyOtpAsync(string mobile,string code,string? fullName=null);Task<ServiceResult<UserProfile>> GetProfileAsync(int userId);Task<ServiceResult<UserProfile>> UpdateProfileAsync(int userId,string fullName,string? email,string language);}
public class AccountService:IAccountService
{private readonly UserManager<User> _users;private readonly ITokenService _tokens;private readonly AppDbContext _db;public AccountService(UserManager<User> users,ITokenService tokens,AppDbContext db){_users=users;_tokens=tokens;_db=db;}
 public async Task<ServiceResult<OtpRequested>> RequestOtpAsync(string mobile){mobile=Normalize(mobile);var recent=await _db.OtpCodes.CountAsync(x=>x.MobileNumber==mobile&&x.CreatedAt>DateTime.UtcNow.AddMinutes(-10));if(recent>=5)return ServiceResult<OtpRequested>.Fail("otp_rate_limited");var code=RandomNumberGenerator.GetInt32(100000,1000000).ToString();_db.OtpCodes.Add(new OtpCode{MobileNumber=mobile,CodeHash=Hash(code),ExpiresAt=DateTime.UtcNow.AddMinutes(5)});_db.WhatsAppMessages.Add(new WhatsAppMessage{MobileNumber=mobile,MessageType="otp",Status=MessageDeliveryStatus.Pending});await _db.SaveChangesAsync();return ServiceResult<OtpRequested>.Ok(new("sent",code));}
 public async Task<ServiceResult<LoginResult>> VerifyOtpAsync(string mobile,string code,string? fullName=null){mobile=Normalize(mobile);var otp=await _db.OtpCodes.Where(x=>x.MobileNumber==mobile&&x.UsedAt==null).OrderByDescending(x=>x.Id).FirstOrDefaultAsync();if(otp==null||otp.ExpiresAt<DateTime.UtcNow)return ServiceResult<LoginResult>.Fail("otp_expired");if(otp.Attempts>=5)return ServiceResult<LoginResult>.Fail("otp_attempts_exceeded");otp.Attempts++;if(otp.CodeHash!=Hash(code)){await _db.SaveChangesAsync();return ServiceResult<LoginResult>.Fail("invalid_otp");}otp.UsedAt=DateTime.UtcNow;var user=await _users.Users.FirstOrDefaultAsync(x=>x.PhoneNumber==mobile);if(user==null){user=new User{UserName=mobile,PhoneNumber=mobile,FullName=fullName??"",IsCustomer=true,PhoneNumberConfirmed=true};var r=await _users.CreateAsync(user);if(!r.Succeeded)return ServiceResult<LoginResult>.Fail("registration_failed",r.Errors.Select(x=>x.Description));}if(user.IsBlocked)return ServiceResult<LoginResult>.Fail("blocked");var isProvider=await _db.ProviderUsers.AnyAsync(x=>x.UserId==user.Id&&x.Status==AccountStatus.Active);await ClaimPendingGifts(user);await _db.SaveChangesAsync();var t=_tokens.CreateAccessToken(user,isProvider);return ServiceResult<LoginResult>.Ok(new LoginResult{AccessToken=t.Value,ExpiresIn=t.ExpiresInSeconds,User=Profile(user,isProvider)});}
 private async Task ClaimPendingGifts(User u){var gifts=await _db.Gifts.Include(x=>x.Order).ThenInclude(x=>x.PurchasedBook).Where(x=>x.RecipientMobile==u.PhoneNumber&&x.Status==GiftStatus.Sent).ToListAsync();foreach(var g in gifts){g.RecipientUserId=u.Id;g.Status=GiftStatus.Claimed;g.ClaimedAt=DateTime.UtcNow;if(g.Order.PurchasedBook!=null)g.Order.PurchasedBook.OwnerUserId=u.Id;}}
 public async Task<ServiceResult<UserProfile>> GetProfileAsync(int id){var u=await _users.FindByIdAsync(id.ToString());if(u==null)return ServiceResult<UserProfile>.Fail("not_found");return ServiceResult<UserProfile>.Ok(Profile(u,await _db.ProviderUsers.AnyAsync(x=>x.UserId==id&&x.Status==AccountStatus.Active)));}
 public async Task<ServiceResult<UserProfile>> UpdateProfileAsync(int id,string name,string? email,string language){var u=await _users.FindByIdAsync(id.ToString());if(u==null)return ServiceResult<UserProfile>.Fail("not_found");u.FullName=name;u.Email=email;u.Language=language;var r=await _users.UpdateAsync(u);if(!r.Succeeded)return ServiceResult<UserProfile>.Fail("update_failed",r.Errors.Select(x=>x.Description));return ServiceResult<UserProfile>.Ok(Profile(u,await _db.ProviderUsers.AnyAsync(x=>x.UserId==id&&x.Status==AccountStatus.Active)));}
 private static UserProfile Profile(User u,bool p)=>new(u.Id,u.FullName,u.PhoneNumber??"",u.Email,u.Language,u.IsCustomer,p,u.IsAdmin);private static string Normalize(string x)=>x.Trim().Replace(" ","");private static string Hash(string x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x)));
}
